  for (i = 0; i < _PB_N; i++)
    {
      /* Pointer to the current row of L for faster, cache-friendly access. */
      DATA_TYPE * restrict Li = L_[i];

      /* Unrolled dot product accumulator:
           sum = sum_{j=0}^{i-1} L[i][j] * x[j]
         We use four independent accumulators (sum0..sum3) to increase
         instruction-level parallelism and make SIMD vectorization easier. */
      DATA_TYPE sum0 = (DATA_TYPE)0;
      DATA_TYPE sum1 = (DATA_TYPE)0;
      DATA_TYPE sum2 = (DATA_TYPE)0;
      DATA_TYPE sum3 = (DATA_TYPE)0;

      int j_unroll = (i / 4) * 4;

      /* Main unrolled loop: handle chunks of 4 elements. */
      for (j = 0; j < j_unroll; j += 4)
        {
          sum0 += Li[j]     * x_[j];
          sum1 += Li[j + 1] * x_[j + 1];
          sum2 += Li[j + 2] * x_[j + 2];
          sum3 += Li[j + 3] * x_[j + 3];
        }

      /* Remainder loop: handle the last 0–3 elements (if any). */
      for (; j < i; ++j)
        {
          sum0 += Li[j] * x_[j];
        }

      /* Combine partial sums and complete the forward substitution
         step for x[i]. */
      DATA_TYPE xi = b_[i] - ((sum0 + sum1) + (sum2 + sum3));

      /* Divide by the diagonal element L[i][i]. */
      xi = xi / Li[i];

      /* Store the final result for this row. */
      x_[i] = xi;
    }
#pragma endscop

}


