		DATA_TYPE POLYBENCH_2D(L,N,N,n,n),
		DATA_TYPE POLYBENCH_1D(x,N,n),
		DATA_TYPE POLYBENCH_1D(b,N,n))
{
  int i, j;

  for (i = 0; i < n; i++)
    {
      x[i] = - 999;
      b[i] =  i ;
      for (j = 0; j <= i; j++)
	L[i][j] = (DATA_TYPE) (i+n-j+1)*2/n;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(x,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("x");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, x[i]);
  }
  POLYBENCH_DUMP_END("x");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_trisolv[[gnu::flatten, gnu::noinline]](int n,
		    DATA_TYPE POLYBENCH_2D(L,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(b,N,n))
{
  int i;

  /* Optimized forward substitution for L * x = b.
   *
   * Original kernel:
   *   for (i = 0; i < N; i++) {
   *     x[i] = b[i];
   *     for (j = 0; j < i; j++)
   *       x[i] -= L[i][j] * x[j];
   *     x[i] = x[i] / L[i][i];
   *   }
   *
   * This version preserves the same computation but improves
   *   - data locality for L by using a row pointer,
   *   - register reuse by keeping the running value of x[i]
   *     in a scalar accumulator,
   *   - instruction‑level parallelism via manual unrolling
   *     of the inner loop.
   *
   * Mathematically:
   *   x[i] = ( b[i] - sum_{j=0}^{i-1} L[i,j] * x[j] ) / L[i,i]
   * which is identical to the original kernel.
   */
#pragma scop
  for (i = 0; i < _PB_N; i++)
    {
      /* Pointer to the i-th row of L.
       * Declared restrict to help the compiler assume that
       * this row does not alias with x or b.
       */
      DATA_TYPE *restrict Li = &L[i][0];

      /* Accumulator for x[i] kept in a register.
       * Start from b[i] (equivalent to x[i] = b[i] in the
       * original kernel) and subtract the dot product
       * L[i,0..i-1] · x[0..i-1].
       */
      DATA_TYPE xi = b[i];

      int j = 0;
      int j_end = i;

      /* Manually unroll the inner loop by 4 to increase ILP.
       * Accesses:
       *   - Li[j]   : contiguous in memory (row-major L)
       *   - x[j]    : contiguous in memory
       * are both unit stride, which is friendly to hardware
       * prefetchers and SIMD vectorization.
       */
      for (; j + 3 < j_end; j += 4)
      {
        xi -= Li[j]     * x[j];
        xi -= Li[j + 1] * x[j + 1];
        xi -= Li[j + 2] * x[j + 2];
        xi -= Li[j + 3] * x[j + 3];
      }

      /* Clean-up loop for the remaining (at most 3)
       * elements when i is not a multiple of 4.
       */
      for (; j < j_end; j++)
      {
        xi -= Li[j] * x[j];
      }

      /* Final division by the diagonal element.
       * Li[i] == L[i][i] as in the original code.
       */
      x[i] = xi / Li[i];
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(L, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(b, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(L), POLYBENCH_ARRAY(x), POLYBENCH_ARRAY(b));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_trisolv (n, POLYBENCH_ARRAY(L), POLYBENCH_ARRAY(x), POLYBENCH_ARRAY(b));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(x)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(L);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(b);

  return 0;
}
